impl<T: gx::Coef> Twist<(), T> {
    /// A value from its coefficients, in blade order.
    #[inline(always)]
    #[allow(clippy::too_many_arguments)]
    pub const fn new(e23: T, e31: T, e12: T, e41: T, e42: T, e43: T, e1i: T, e2i: T, e3i: T, e4i: T) -> Self {
        Twist { c: [e23, e31, e12, e41, e42, e43, e1i, e2i, e3i, e4i] }
    }

    /// gx::Prepare this versor's action on kind `X` for applying it to many objects (see
    /// [`gx::Prepared`]).
    #[inline(always)]
    pub fn prepare<X>(self) -> <Self as gx::Prepare<X>>::Output
    where
        Self: gx::Prepare<X>,
    {
        gx::Prepare::prepare(self)
    }

    /// The identity map on `Twist`: a `Twist` with one open `Twist` slot.
    #[inline(always)]
    pub fn slot() -> Twist<(Twist,), T> {
        Twist { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `e23`.
    #[inline(always)]
    pub fn e23(&self) -> T {
        self.c[0]
    }

    /// Coefficient of `e31`.
    #[inline(always)]
    pub fn e31(&self) -> T {
        self.c[1]
    }

    /// Coefficient of `e12`.
    #[inline(always)]
    pub fn e12(&self) -> T {
        self.c[2]
    }

    /// Coefficient of `e41`.
    #[inline(always)]
    pub fn e41(&self) -> T {
        self.c[3]
    }

    /// Coefficient of `e42`.
    #[inline(always)]
    pub fn e42(&self) -> T {
        self.c[4]
    }

    /// Coefficient of `e43`.
    #[inline(always)]
    pub fn e43(&self) -> T {
        self.c[5]
    }

    /// Coefficient of `e1i`.
    #[inline(always)]
    pub fn e1i(&self) -> T {
        self.c[6]
    }

    /// Coefficient of `e2i`.
    #[inline(always)]
    pub fn e2i(&self) -> T {
        self.c[7]
    }

    /// Coefficient of `e3i`.
    #[inline(always)]
    pub fn e3i(&self) -> T {
        self.c[8]
    }

    /// Coefficient of `e4i`.
    #[inline(always)]
    pub fn e4i(&self) -> T {
        self.c[9]
    }
}

