impl<T: gx::Real> Quintvector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t4 = x[4] * x[5];
        let t5 = x[0].mul_add(x[0], t1);
        let t6 = (-x[3]).mul_add(x[3], t2);
        let t7 = t5 + t6;
        let t9 = t4.mul_add(T::from_i64(2), t7);
        t9
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (34 mul, 18 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Quintvector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = x[4] * x[5];
        let t7 = t0 * t2;
        let t10 = t1 * t1;
        let t12 = t1 * t3;
        let t13 = t1 * t4;
        let t17 = t3 * t3;
        let t19 = t4 * t4;
        let t20 = t0.mul_add(t0, t10);
        let t21 = t2.mul_add(t2, t17);
        let t22 = t20 + t21;
        let t23 = t0.mul_add(t1, t7);
        let t24 = t1.mul_add(t2, t23);
        let t25 = t0.mul_add(t3, t12);
        let t26 = t2.mul_add(t3, t25);
        let t27 = t24 - t26;
        let t29 = t0.mul_add(t4, t13);
        let t30 = t2.mul_add(t4, t29);
        let t31 = (-t3).mul_add(t4, t19);
        let t32 = t30 + t31;
        let t34 = t27.mul_add(T::from_i64(2), t22);
        let t35 = t32.mul_add(T::from_i64(4), t34);
        let t36 = t35.recip();
        let t38 = t1 * t36;
        let t39 = t2 * t36;
        let t41 = t4 * t36;
        let t42 = t0.mul_add(t36, t38);
        let t43 = (-t3).mul_add(t36, t39);
        let t44 = t42 + t43;
        let t46 = t41.mul_add(T::from_i64(2), t44);
        let t47 = x[0] * t46;
        let t48 = x[1] * t46;
        let t49 = x[2] * t46;
        let t50 = x[3] * t46;
        let t51 = x[4] * t46;
        let t52 = x[5] * t46;
        Quintvector::from_coeffs([t47, t48, t49, t50, t51, t52])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p2 = x[2] * x[2];
        let p4 = x[4] * x[5];
        let p5 = x[0].mul_add(x[0], p1);
        let p6 = (-x[3]).mul_add(x[3], p2);
        let p7 = p5 + p6;
        let p9 = p4.mul_add(T::from_i64(2), p7);
        let s0 = (p9).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[4] * s0;
        let t5 = x[5] * s0;
        gx::Unit::new_unchecked(Quintvector::from_coeffs([t0, t1, t2, t3, t4, t5]))
    }

}

#[doc = "The pseudoscalar `e1234oi`."]
///
/// Blades, in coefficient order: `[e1234oi]`.
///
/// `S` lists the open slots: `Pseudoscalar` (that is, `Pseudoscalar<()>`) is a value, `Pseudoscalar<(A,)>` a
/// linear map from `A`, `Pseudoscalar<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Pseudoscalar<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 1],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Pseudoscalar<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Pseudoscalar<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Pseudoscalar<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Pseudoscalar<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Pseudoscalar");
        for (b, c) in <Pseudoscalar as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Pseudoscalar {
    const N: usize = 1;
    const NAME: &'static str = "Pseudoscalar";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e1234oi"];
    type Arr<X: gx::Elem> = [X; 1];
    type Mv<S: gx::Slots, T: gx::Coef> = Pseudoscalar<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 1] {
        [f(0)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 1], mut f: impl FnMut(&X) -> Y) -> [Y; 1] {
        [f(&a[0])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 1],
        b: &[Y; 1],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 1] {
        [f(&a[0], &b[0])]
    }
}

