impl<T: gx::Real> Pseudoscalar<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (4 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Pseudoscalar<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t1 * t3;
        let t5 = -t4;
        Pseudoscalar::from_coeffs([t5])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Pseudoscalar::from_coeffs([t0]))
    }

}

#[doc = "A PoincarÃ© motion: a Lorentz transformation and a translation."]
///
/// Blades, in coefficient order: `[1, e23, e31, e12, e41, e42, e43, e1i, e2i, e3i, e4i, e234i, e314i, e124i, e123i, e1234]`.
///
/// `S` lists the open slots: `Motor` (that is, `Motor<()>`) is a value, `Motor<(A,)>` a
/// linear map from `A`, `Motor<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Motor<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 16],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Motor<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Motor<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Motor<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Motor<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Motor");
        for (b, c) in <Motor as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Motor {
    const N: usize = 16;
    const NAME: &'static str = "Motor";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["1", "e23", "e31", "e12", "e41", "e42", "e43", "e1i", "e2i", "e3i", "e4i", "e234i", "e314i", "e124i", "e123i", "e1234"];
    type Arr<X: gx::Elem> = [X; 16];
    type Mv<S: gx::Slots, T: gx::Coef> = Motor<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 16] {
        [f(0), f(1), f(2), f(3), f(4), f(5), f(6), f(7), f(8), f(9), f(10), f(11), f(12), f(13), f(14), f(15)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 16], mut f: impl FnMut(&X) -> Y) -> [Y; 16] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5]), f(&a[6]), f(&a[7]), f(&a[8]), f(&a[9]), f(&a[10]), f(&a[11]), f(&a[12]), f(&a[13]), f(&a[14]), f(&a[15])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 16],
        b: &[Y; 16],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 16] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5]), f(&a[6], &b[6]), f(&a[7], &b[7]), f(&a[8], &b[8]), f(&a[9], &b[9]), f(&a[10], &b[10]), f(&a[11], &b[11]), f(&a[12], &b[12]), f(&a[13], &b[13]), f(&a[14], &b[14]), f(&a[15], &b[15])]
    }
}

