impl<T: gx::Real> Motor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[3];
        let t5 = x[5] * x[5];
        let t7 = x[15] * x[15];
        let t8 = x[0].mul_add(x[0], t1);
        let t9 = x[2].mul_add(x[2], t3);
        let t10 = t8 + t9;
        let t11 = x[4].mul_add(x[4], t5);
        let t12 = x[6].mul_add(x[6], t7);
        let t13 = t11 + t12;
        let t14 = t10 - t13;
        t14
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

}

impl<T: gx::Real> gx::Log<Twist<(), T>> for gx::Unit<Motor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Twist<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p0 = x[15] * x[15];
        let p1 = -p0;
        let [h0, h1] = gx::study::log_coeffs_q(x[0], p1);
        let t0 = x[15] * h1;
        let t1 = x[11] * h1;
        let t2 = x[12] * h1;
        let t3 = x[13] * h1;
        let t4 = x[14] * h1;
        let t5 = x[1] * h0;
        let t7 = x[2] * h0;
        let t9 = x[3] * h0;
        let t12 = x[4] * h0;
        let t14 = x[5] * h0;
        let t16 = x[6] * h0;
        let t18 = x[5] * t3;
        let t20 = x[7] * h0;
        let t23 = x[6] * t1;
        let t24 = x[8] * h0;
        let t26 = x[4] * t2;
        let t28 = x[9] * h0;
        let t31 = x[3] * t3;
        let t32 = x[10] * h0;
        let t33 = (-x[4]).mul_add(t0, t5);
        let t34 = (-x[5]).mul_add(t0, t7);
        let t35 = (-x[6]).mul_add(t0, t9);
        let t36 = x[1].mul_add(t0, t12);
        let t37 = x[2].mul_add(t0, t14);
        let t38 = x[3].mul_add(t0, t16);
        let t39 = x[6].mul_add(t2, t20);
        let t40 = x[1].mul_add(t4, t18);
        let t41 = t39 - t40;
        let t42 = x[4].mul_add(t3, t24);
        let t43 = x[2].mul_add(t4, t23);
        let t44 = t42 - t43;
        let t45 = x[5].mul_add(t1, t28);
        let t46 = x[3].mul_add(t4, t26);
        let t47 = t45 - t46;
        let t48 = (-x[1]).mul_add(t1, t32);
        let t49 = x[2].mul_add(t2, t31);
        let t50 = t48 - t49;
        Twist::from_coeffs([t33, t34, t35, t36, t37, t38, t41, t44, t47, t50])
        })
    }
}

#[doc = "The even subalgebra: all conformal versors of even grade (their sandwiches go through the general product; `Motor` has fused kernels)."]
///
/// Blades, in coefficient order: `[1, e23, e31, e12, e41, e42, e43, e1o, e2o, e3o, e4o, e1i, e2i, e3i, e4i, eoi, e1234, e234o, e314o, e124o, e123o, e234i, e314i, e124i, e123i, e23oi, e31oi, e12oi, e41oi, e42oi, e43oi, e1234oi]`.
///
/// `S` lists the open slots: `Even` (that is, `Even<()>`) is a value, `Even<(A,)>` a
/// linear map from `A`, `Even<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Even<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 32],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Even<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Even<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Even<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Even<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Even");
        for (b, c) in <Even as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

