impl<S1: gx::Slots, S2: gx::Slots, T: gx::Coef> gx::Gp<Scalar<S2, T>> for Quintvector<S1, T> {
    type Output = Quintvector<gx::Cat<S1, S2>, T>;
    #[inline(always)]
    fn gp(self, rhs: Scalar<S2, T>) -> Quintvector<gx::Cat<S1, S2>, T> {
        let a = self.c.map(gx::SlotArr::<S1, T>);
        let b = rhs.c.map(gx::SlotArr::<S2, T>);
        Quintvector {
            c: [
                (a[0] * b[0]).0,
                (a[1] * b[0]).0,
                (a[2] * b[0]).0,
                (a[3] * b[0]).0,
                (a[4] * b[0]).0,
                (a[5] * b[0]).0,
            ],
        }
    }
}

