        let t40 = v[3] * xv[5];
        let t42 = (-v[4]).mul_add(xv[8], t40);
        let t43 = v[3] * xv[6];
        let t45 = (-v[4]).mul_add(xv[9], t43);
        let t46 = v[2] * xv[10];
        let t48 = (-v[5]).mul_add(xv[6], t46);
        let t49 = t10 + t36;
        let t50 = v[4] * v[5];
        let t51 = t2 * T::from_f64(1.0 / 2.0);
